52:     mttrHoursSaved: Number(mttrHours.toFixed(2)),
53:     hourlyEngineerRateUSD: rate,
54:     grossSavingsUSD: Number(grossSavings.toFixed(2)),
55:     netSavingsUSD: Number(netSavings.toFixed(2)),
56:     grossMarginPercent: Math.round(margin * 10) / 10
57:   };
58: }
